/*
 * Hand-written part of the API reference: sections and the endpoints worth
 * explaining. Every other route is still listed (api/introspect.js finds them
 * all), with its scope, just without prose.
 *
 * Keys are "METHOD /path" exactly as the route is declared, relative to /api.
 * Texts are L(ru, en, ky, tr, zh) — pick() falls back to English for a missing language.
 */

const L = (ru, en, ky, tr, zh) => ({ ru, en, ky, tr, zh });
const q = (name, type, desc, extra = {}) => ({ name, type, desc, ...extra });
const b = (name, type, desc, extra = {}) => ({ name, type, desc, ...extra });

export const SECTIONS = [
  { key: 'account', area: 'account', prefix: ['/auth/me', '/account'], title: L('Профиль', 'Account', 'Профиль', 'Hesap', '账户'), intro: L('Кто владелец токена и его профиль.', 'Who owns the token, and their profile.', 'Токендин ээси ким жана анын профили.', 'Belirtecin sahibi kim ve profili.', '令牌的所有者及其个人资料。') },
  { key: 'notifications', area: 'notifications', prefix: ['/notifications'], title: L('Уведомления', 'Notifications', 'Билдирмелер', 'Bildirimler', '通知'), intro: L('Входящие уведомления владельца токена: список, счётчик, отметка о прочтении.', "The token owner's inbox: list, counter, marking as read.", 'Токен ээсинин кирүүчү билдирмелери: тизме, эсептегич, окулду деп белгилөө.', 'Belirteç sahibinin gelen kutusu: liste, sayaç, okundu olarak işaretleme.', '令牌所有者的收件箱：列表、计数、标记为已读。') },
  { key: 'tasks', area: 'tasks', prefix: ['/app/tasks'], title: L('Задачи', 'Tasks', 'Тапшырмалар', 'Görevler', '任务'), intro: L('Проекты, задачи, чек-листы, результаты, файлы, шаблоны и потоки. Задача адресуется ссылкой `KEY-12` или числовым id.', 'Projects, tasks, checklists, results, files, templates and flows. A task is addressed by its reference `KEY-12` or numeric id.', 'Долбоорлор, тапшырмалар, текшерүү тизмелери, жыйынтыктар, файлдар, үлгүлөр жана агымдар. Тапшырма `KEY-12` шилтемеси же сандык id аркылуу көрсөтүлөт.', 'Projeler, görevler, kontrol listeleri, sonuçlar, dosyalar, şablonlar ve akışlar. Bir göreve `KEY-12` referansı veya sayısal id ile erişilir.', '项目、任务、检查清单、结果、文件、模板和任务流。任务通过引用 `KEY-12` 或数字 id 指定。') },
  { key: 'chat', area: 'chat', prefix: ['/app/chat'], title: L('Чат', 'Chat', 'Чат', 'Sohbet', '聊天'), intro: L('Личные, групповые чаты и чаты записей (например, задачи). Для событий в реальном времени — поток SSE или вебхук `chat.message`.', 'Direct, group and record conversations (e.g. a task). For real time use the SSE stream or the `chat.message` webhook.', 'Жеке, топтук чаттар жана жазуулардын чаттары (мисалы, тапшырма). Реалдуу убакыт үчүн SSE агымын же `chat.message` вебхугун колдонуңуз.', 'Birebir, grup ve kayıt sohbetleri (ör. bir görev). Gerçek zamanlı için SSE akışını veya `chat.message` web kancasını kullanın.', '私聊、群聊和记录会话（例如任务）。实时消息请使用 SSE 流或 `chat.message` Webhook。') },
  { key: 'calendar', area: 'calendar', prefix: ['/app/calendar'], title: L('Календарь', 'Calendar', 'Календарь', 'Takvim', '日历'), intro: L('Календари и события с повторениями, участниками и напоминаниями. Даты — ISO 8601.', 'Calendars and events with recurrence, attendees and reminders. Dates are ISO 8601.', 'Кайталоолору, катышуучулары жана эскертүүлөрү бар календарлар жана иш-чаралар. Даталар — ISO 8601.', 'Yinelenme, katılımcılar ve hatırlatıcılarla takvimler ve etkinlikler. Tarihler ISO 8601\'dir.', '带重复规则、参与者和提醒的日历与日程。日期为 ISO 8601。') },
  { key: 'companies', area: 'companies', prefix: ['/app/companies'], title: L('Контрагенты', 'Counterparties', 'Контрагенттер', 'Cari hesaplar', '往来单位'), intro: L('Компании и контакты, проверка по реестрам, заметки и оценки.', 'Companies and people, registry checks, notes and ratings.', 'Компаниялар жана адамдар, реестрлер боюнча текшерүү, жазуулар жана баалар.', 'Şirketler ve kişiler, sicil kontrolleri, notlar ve puanlar.', '公司和联系人、登记信息核查、备注和评分。') },
  { key: 'crm', area: 'crm', prefix: ['/app/crm'], title: L('CRM', 'CRM', 'CRM', 'CRM', 'CRM'), intro: L('Сделки по стадиям воронок, дела, история, фильтры. Клиенты — компании и люди модуля «Контрагенты». Суммы — числа с двумя знаками, валюты — ISO 4217. Видимость сделок та же, что в интерфейсе; токен можно ограничить воронками (`crm.pipelines`).', 'Deals moving through pipeline stages, activities, history, filters. Clients are companies and people of the Counterparties module. Amounts are numbers with two decimals, currencies ISO 4217. Deals are visible as in the UI; a token can be narrowed to pipelines (`crm.pipelines`).', 'Воронканын баскычтары боюнча жылган бүтүмдөр, иш-чаралар, тарых, чыпкалар. Кардарлар — «Контрагенттер» модулунун компаниялары жана адамдары. Суммалар — эки белгиси бар сандар, валюталар — ISO 4217. Бүтүмдөр интерфейстегидей көрүнөт; токенди воронкалар менен чектөөгө болот (`crm.pipelines`).', 'Satış hattı aşamalarında ilerleyen fırsatlar, aktiviteler, geçmiş, filtreler. Müşteriler Cari hesaplar modülünün şirketleri ve kişileridir. Tutarlar iki ondalıklı sayılar, para birimleri ISO 4217. Fırsatlar arayüzdeki gibi görünür; bir belirteç satış hatlarıyla sınırlandırılabilir (`crm.pipelines`).', '在销售漏斗各阶段推进的交易、活动、历史、筛选。客户是“往来单位”模块中的公司和联系人。金额为两位小数的数字，货币为 ISO 4217。交易可见性与界面一致；令牌可限定到指定漏斗（`crm.pipelines`）。') },
  { key: 'approvals', area: 'approvals', prefix: ['/app/approvals'], title: L('Согласования', 'Approvals', 'Макулдашуулар', 'Onaylar', '审批'), intro: L('Сервис согласований: «Ждёт меня», процессы документов, решения (согласовать, отклонить, вопрос, вернуть, делегировать), маршруты, срочность и замещения. Процесс адресуется числовым id или парой «тип + id документа» (`procurement.request` / `42`). Решение принимает `round` и `stage`, которые видел человек: если процесс ушёл дальше — 409 `STALE`.', 'The approvals service: the «Waiting for me» inbox, document processes, decisions (approve, reject, question, return, delegate), routes, urgency and substitutes. A process is addressed by its numeric id or by type + document id (`procurement.request` / `42`). A decision takes the `round` and `stage` the person saw; if the process has moved on the answer is 409 `STALE`.', 'Макулдашуу кызматы: «Мени күтүүдө» кирүүчүлөрү, документтердин процесстери, чечимдер (макулдашуу, четке кагуу, суроо, кайтаруу, башкага өткөрүп берүү), маршруттар, шашылыштык жана орун басарлар. Процесс сандык id же «түрү + документтин id» жубу (`procurement.request` / `42`) аркылуу көрсөтүлөт. Чечим адам көргөн `round` жана `stage` маанилерин алат; эгер процесс алдыга жылып кетсе, жооп 409 `STALE`.', 'Onay hizmeti: «Beni bekleyenler» gelen kutusu, belge süreçleri, kararlar (onayla, reddet, soru, geri gönder, devret), akışlar, aciliyet ve vekiller. Bir sürece sayısal id\'si veya tür + belge id\'si (`procurement.request` / `42`) ile erişilir. Karar, kişinin gördüğü `round` ve `stage` değerlerini alır; süreç ilerlemişse yanıt 409 `STALE` olur.', '审批服务：“待我处理”收件箱、单据流程、决定（批准、拒绝、提问、退回、转交）、流程路线、紧急程度和代理人。流程通过数字 id 或“类型 + 单据 id”（`procurement.request` / `42`）指定。决定需带上当事人看到的 `round` 和 `stage`；若流程已推进，返回 409 `STALE`。') },
  { key: 'procurement', area: 'procurement', prefix: ['/app/procurement'], title: L('Закупки', 'Procurement', 'Сатып алуулар', 'Satın alma', '采购'), intro: L('Заявки на закупку: позиции или одна сумма, валюта, юрлицо-плательщик, условия оплаты, срочность, «оплатить до» / «поставить до», поставщик, привязки (проект, сделка, договор), документы. Согласование — через сервис согласований (тип `procurement.request`); после согласования заявка сама становится «К оплате». Оплаты (несколько частичных) и поставка меняют статус по правилам сервера. Видны свои заявки, заявки коллег по группам и те, где человек согласующий; `procurement.view_all` — все, `procurement.pay` — согласованные. Суммы — числа с двумя знаками, даты — `YYYY-MM-DD`.', 'Purchase requests: line items or one amount, currency, paying legal entity, payment terms, urgency, pay by / deliver by, supplier, links (project, deal, contract), documents. Approval goes through the approvals service (type `procurement.request`); an approved request becomes «to pay» by itself. Payments (several partial ones) and delivery move the status by the server rules. People see their own requests, those of colleagues from their groups and those they approve; `procurement.view_all`: all, `procurement.pay`: approved ones. Amounts are numbers with two decimals, dates `YYYY-MM-DD`.', 'Сатып алууга өтүнмөлөр: позициялар же бир сумма, валюта, төлөөчү юридикалык жак, төлөм шарттары, шашылыштык, «качанга чейин төлөө» / «качанга чейин жеткирүү», жеткирүүчү, байланыштар (долбоор, бүтүм, келишим), документтер. Макулдашуу — макулдашуу кызматы аркылуу (`procurement.request` түрү); макулдашылган өтүнмө өзү «Төлөөгө» абалына өтөт. Төлөмдөр (бир нече жарым-жартылай) жана жеткирүү статусту сервердин эрежелери боюнча өзгөртөт. Ар ким өз өтүнмөлөрүн, өз топторундагы кесиптештердин өтүнмөлөрүн жана өзү макулдашуучу болгон өтүнмөлөрдү көрөт; `procurement.view_all` — баарын, `procurement.pay` — макулдашылгандарын. Суммалар — эки белгиси бар сандар, даталар — `YYYY-MM-DD`.', 'Satın alma talepleri: kalemler veya tek tutar, para birimi, ödeyen tüzel kişi, ödeme koşulları, aciliyet, son ödeme / teslim tarihi, tedarikçi, bağlantılar (proje, fırsat, sözleşme), belgeler. Onay, onay hizmeti üzerinden yapılır (`procurement.request` türü); onaylanan talep kendiliğinden «ödenecek» olur. Ödemeler (birden çok kısmi ödeme) ve teslimat durumu sunucu kurallarına göre değiştirir. Kişiler kendi taleplerini, gruplarındaki iş arkadaşlarının taleplerini ve onayladıklarını görür; `procurement.view_all`: tümü, `procurement.pay`: onaylananlar. Tutarlar iki ondalıklı sayılar, tarihler `YYYY-MM-DD`.', '采购申请：明细行或单一金额、货币、付款法人实体、付款条件、紧急程度、付款截止 / 交货截止、供应商、关联（项目、交易、合同）、文件。审批通过审批服务进行（类型 `procurement.request`）；审批通过的申请自动变为“待付款”。付款（可多次部分付款）和交货按服务器规则改变状态。用户可见自己的申请、本组同事的申请以及自己审批的申请；`procurement.view_all`：全部，`procurement.pay`：已审批的申请。金额为两位小数的数字，日期为 `YYYY-MM-DD`。') },
  { key: 'warehouse', area: 'warehouse', prefix: ['/app/warehouse'], title: L('Склад', 'Warehouse', 'Кампа', 'Depo', '仓库'), intro: L('Складской учёт: номенклатура (единицы с коэффициентами, штрихкоды, партии, серийные номера), склады с ячейками, остатки с резервами и средней себестоимостью, документы (приход, в том числе из заявки Закупок; возврат поставщику; перемещение в два шага с актом расхождения; выдача сотруднику или на объект; возврат; списание с согласованием выше порога; ввод остатков; корректировка; передача инструмента; сторно), инструмент, отчёты, импорт. Количества — в базовых единицах позиции (`baseQty`) и в единицах строки (`qty` + `unit`, `factor`). Права — по складам (`warehouse.*` на все склады или назначение на один склад, МОЛ). Без права `warehouse.cost` суммы удаляются из всех ответов, отчётов и выгрузок; в вебхуках сумм нет никогда. Ошибка `409 INSUFFICIENT` несёт `info.shortages: [{ itemId, name, need, available, short }]`.', 'Warehouse accounting: items (units with factors, barcodes, batches, serial numbers), warehouses with bins, stock with reserves and moving-average cost, documents (receipt, also from a Procurement request; return to supplier; two-step transfer with a discrepancy act; issue to a person or an object; return; write-off with approval above the threshold; opening balances; correction; tool hand-over; storno), tools, reports, import. Quantities come in the item base unit (`baseQty`) and in the line unit (`qty` + `unit`, `factor`). Rights are per warehouse (`warehouse.*` everywhere or an assignment on one warehouse, the MOL). Without `warehouse.cost` sums are removed from every answer, report and export; webhooks never carry sums. `409 INSUFFICIENT` carries `info.shortages: [{ itemId, name, need, available, short }]`.', 'Кампа эсеби: номенклатура (коэффициенттери бар бирдиктер, штрихкоддор, партиялар, сериялык номерлер), уячалары бар кампалар, резервдери жана орточо өздүк наркы бар калдыктар, документтер (кирим, анын ичинде «Сатып алуулар» өтүнмөсүнөн; жеткирүүчүгө кайтаруу; айырмачылык акты менен эки кадамдуу которуу; кызматкерге же объектке берүү; кайтаруу; чектен жогору макулдашуу менен эсептен чыгаруу; калдыктарды киргизүү; оңдоо; шайманды өткөрүп берүү; сторно), шаймандар, отчеттор, импорт. Сандар позициянын негизги бирдигинде (`baseQty`) жана саптын бирдигинде (`qty` + `unit`, `factor`) берилет. Укуктар кампалар боюнча (`warehouse.*` бардык кампаларга же бир кампага дайындоо, МЖА). `warehouse.cost` укугусуз суммалар бардык жооптордон, отчеттордон жана жүктөөлөрдөн алынып салынат; вебхуктарда суммалар эч качан болбойт. `409 INSUFFICIENT` катасы `info.shortages: [{ itemId, name, need, available, short }]` алып жүрөт.', 'Depo muhasebesi: stok kartları (katsayılı birimler, barkodlar, partiler, seri numaraları), lokasyonlu depolar, rezervli ve hareketli ortalama maliyetli stok, belgeler (giriş, Satın alma talebinden de; tedarikçiye iade; fark tutanaklı iki adımlı transfer; bir kişiye veya bir şantiyeye çıkış; iade; eşik üstünde onaylı hurdaya ayırma; açılış stokları; düzeltme; alet teslimi; ters kayıt), aletler, raporlar, içe aktarma. Miktarlar kalemin temel biriminde (`baseQty`) ve satır biriminde (`qty` + `unit`, `factor`) gelir. Haklar depo bazındadır (her yerde `warehouse.*` veya tek bir depoya atama, zimmet sorumlusu). `warehouse.cost` olmadan tutarlar tüm yanıtlardan, raporlardan ve dışa aktarmalardan çıkarılır; web kancaları asla tutar taşımaz. `409 INSUFFICIENT` hatası `info.shortages: [{ itemId, name, need, available, short }]` taşır.', '仓库核算：物料（带换算系数的单位、条形码、批次、序列号）、带库位的仓库、含预留和移动平均成本的库存、单据（入库，也可来自采购申请；退货给供应商；带差异单的两步调拨；向人员或对象出库；退库；超过阈值需审批的报废；期初库存；调整；工具交接；冲销）、工具、报表、导入。数量以物料基本单位（`baseQty`）和行单位（`qty` + `unit`、`factor`）表示。权限按仓库划分（`warehouse.*` 适用于所有仓库，或分配到某一仓库，即物资责任人）。没有 `warehouse.cost` 时，所有响应、报表和导出中的金额都会被移除；Webhook 从不携带金额。`409 INSUFFICIENT` 带有 `info.shortages: [{ itemId, name, need, available, short }]`。') },
  { key: 'contracts', area: 'contracts', prefix: ['/app/contracts'], title: L('Договоры', 'Contracts', 'Келишимдер', 'Sözleşmeler', '合同'), intro: L('Реестр договоров: карточка (тип, направление, контрагент, юрлицо, сумма или «рамочный», сроки, автопролонгация), версии файла, риски юриста, связи, история. Согласование — через сервис согласований (тип `contracts.contract`). Статусы меняются только по правилам: «Подписан», «Действует», «Завершён», «Расторгнут» — у `contracts.legal`; «Истекает» и «Действует» ставятся по датам автоматически. Видны свои договоры, договоры своей группы и те, где человек согласующий (`contracts.view_all` — все). Даты — `YYYY-MM-DD`.', 'The contracts registry: the card (type, direction, counterparty, legal entity, amount or framework, dates, auto-prolongation), file versions, the lawyer’s risks, links, history. Approval goes through the approvals service (type `contracts.contract`). Statuses change only by the rules: signed, in force, completed, terminated need `contracts.legal`; expiring and in force are set from the dates automatically. People see their own contracts, their group’s and those they approve (`contracts.view_all`: all). Dates are `YYYY-MM-DD`.', 'Келишимдер реестри: карточка (түрү, багыты, контрагент, юридикалык жак, сумма же алкактык, мөөнөттөр, автоматтык узартуу), файлдын версиялары, юристтин тобокелдиктери, байланыштар, тарых. Макулдашуу — макулдашуу кызматы аркылуу (`contracts.contract` түрү). Статустар эрежелер боюнча гана өзгөрөт: «Кол коюлду», «Күчүндө», «Аткарылды», «Бузулду» — `contracts.legal` укугу менен; «Мөөнөтү бүтүүдө» жана «Күчүндө» даталар боюнча автоматтык түрдө коюлат. Ар ким өз келишимдерин, өз тобунун келишимдерин жана өзү макулдашуучу болгон келишимдерди көрөт (`contracts.view_all` — баарын). Даталар — `YYYY-MM-DD`.', 'Sözleşme kayıt listesi: kart (tür, yön, cari hesap, tüzel kişi, tutar veya çerçeve, tarihler, otomatik uzatma), dosya sürümleri, hukukçu riskleri, bağlantılar, geçmiş. Onay, onay hizmeti üzerinden yapılır (`contracts.contract` türü). Durumlar yalnızca kurallara göre değişir: imzalandı, yürürlükte, tamamlandı, feshedildi için `contracts.legal` gerekir; süresi doluyor ve yürürlükte tarihlerden otomatik olarak ayarlanır. Kişiler kendi sözleşmelerini, gruplarınınkileri ve onayladıklarını görür (`contracts.view_all`: tümü). Tarihler `YYYY-MM-DD`.', '合同台账：卡片（类型、方向、往来单位、法人实体、金额或框架合同、日期、自动续期）、文件版本、律师风险提示、关联、历史。审批通过审批服务进行（类型 `contracts.contract`）。状态只能按规则变更：已签署、生效中、已履行、已解除需要 `contracts.legal`；即将到期和生效中由日期自动设置。用户可见自己的合同、本组的合同以及自己审批的合同（`contracts.view_all`：全部）。日期为 `YYYY-MM-DD`。') },
  { key: 'masterplan', area: 'masterplan', prefix: ['/app/masterplan'], title: L('Мастерплан', 'Masterplan', 'Мастерплан', 'Master plan', '总体规划'), intro: L('Проекты застройки: дерево объектов, генплан с контурами, статусы продаж с бронированием, цены, ход строительства и фотоотчёты. Права — роли модуля с зонами ответственности; чувствительные поля (минимальная цена, клиенты, суммы) сервер скрывает по ролям. Смена статуса принимает `version` — при устаревшей версии 409 `VERSION_CONFLICT` с текущим держателем в `info.holder`.', 'Development projects: the object tree, the site plan with contours, sales statuses with bookings, prices, construction progress and photo reports. Rights are module roles with zones of responsibility; the server hides sensitive fields (minimum price, clients, amounts) by role. Status changes take `version`; a stale one answers 409 `VERSION_CONFLICT` with the current holder in `info.holder`.', 'Курулуш долбоорлору: объекттердин дарагы, контурлары бар башкы план, брондоо менен сатуу статустары, баалар, курулуштун жүрүшү жана сүрөт отчеттору. Укуктар — жоопкерчилик зоналары бар модулдун ролдору; сезимтал талааларды (минималдуу баа, кардарлар, суммалар) сервер ролдор боюнча жашырат. Статусту өзгөртүү `version` маанисин алат — эскирген версияда 409 `VERSION_CONFLICT` жана `info.holder` ичинде учурдагы ээси кайтарылат.', 'Geliştirme projeleri: nesne ağacı, konturlu vaziyet planı, rezervasyonlu satış durumları, fiyatlar, inşaat ilerlemesi ve fotoğraflı raporlar. Haklar, sorumluluk alanlarına sahip modül rolleridir; sunucu hassas alanları (asgari fiyat, müşteriler, tutarlar) role göre gizler. Durum değişiklikleri `version` alır; eskimiş bir sürüm, `info.holder` içinde mevcut sahibiyle 409 `VERSION_CONFLICT` döndürür.', '开发项目：对象树、带轮廓的总平面图、含预订的销售状态、价格、施工进度和照片报告。权限为带责任区域的模块角色；服务器按角色隐藏敏感字段（最低价、客户、金额）。状态变更需带 `version`；版本过期时返回 409 `VERSION_CONFLICT`，并在 `info.holder` 中给出当前持有人。') },
  { key: 'files', area: 'files', prefix: ['/app/files'], title: L('Файлы', 'Files', 'Файлдар', 'Dosyalar', '文件'), intro: L('Личные файлы и общие пространства: папки, загрузка, скачивание, доступ и ссылки.', 'Personal files and shared spaces: folders, upload, download, sharing and links.', 'Жеке файлдар жана жалпы мейкиндиктер: папкалар, жүктөө, жүктөп алуу, кирүү укугу жана шилтемелер.', 'Kişisel dosyalar ve paylaşılan alanlar: klasörler, yükleme, indirme, paylaşım ve bağlantılar.', '个人文件和共享空间：文件夹、上传、下载、共享和链接。') },
  { key: 'kb', area: 'kb', prefix: ['/app/kb'], title: L('База знаний', 'Knowledge base', 'Билим базасы', 'Bilgi bankası', '知识库'), intro: L('Папки и материалы базы знаний.', 'Knowledge base folders and items.', 'Билим базасынын папкалары жана материалдары.', 'Bilgi bankası klasörleri ve içerikleri.', '知识库文件夹和内容。') },
  { key: 'drive', area: 'drive', prefix: ['/app/drive'], title: L('Файловый сервер', 'File server', 'Файл сервери', 'Dosya sunucusu', '文件服务器'), intro: L('Сетевые папки (SMB): список, чтение, загрузка. Пути передаются параметром `path`.', 'Network shares (SMB): listing, reading, uploading. Paths go in the `path` parameter.', 'Тармактык папкалар (SMB): тизме, окуу, жүктөө. Жолдор `path` параметри менен берилет.', 'Ağ paylaşımları (SMB): listeleme, okuma, yükleme. Yollar `path` parametresiyle verilir.', '网络共享（SMB）：列出、读取、上传。路径通过 `path` 参数传递。') },
  { key: 'resources', area: 'resources', prefix: ['/app/resources'], title: L('Онлайн-ресурсы', 'Online resources', 'Онлайн ресурстар', 'Çevrimiçi kaynaklar', '在线资源'), intro: L('Плитки ссылок и их порядок.', 'Link tiles and their order.', 'Шилтемелердин плиткалары жана алардын тартиби.', 'Bağlantı kutucukları ve sıraları.', '链接磁贴及其顺序。') },
  { key: 'dashboard', area: 'dashboard', prefix: ['/app/dashboard'], title: L('Дашборд', 'Dashboard', 'Башкаруу панели', 'Pano', '仪表板'), intro: L('Виджеты владельца токена и данные для них.', "The token owner's widgets and their data.", 'Токен ээсинин виджеттери жана алар үчүн маалыматтар.', 'Belirteç sahibinin pencere öğeleri ve verileri.', '令牌所有者的小组件及其数据。') },
  { key: 'org', area: 'org', prefix: ['/app/org'], title: L('Оргструктура', 'Org structure', 'Уюмдук түзүм', 'Organizasyon yapısı', '组织架构'), intro: L('Дерево подразделений: типы, руководители, назначения, часовые пояса, история перемещений. Читать может любой вошедший; менять — с правом `org.manage`. `GET /app/org/manager/:userId` отвечает, кто для человека «руководитель подразделения».', 'The tree of units: types, heads, purposes, time zones, history of moves. Anyone signed in reads it; changes need `org.manage`. `GET /app/org/manager/:userId` answers who is the person’s «head of unit».', 'Бөлүмдөрдүн дарагы: түрлөр, жетекчилер, багыттар, саат алкактары, жылдыруулардын тарыхы. Кирген ар бир адам окуй алат; өзгөртүү үчүн `org.manage` керек. `GET /app/org/manager/:userId` адам үчүн «бөлүмдүн жетекчиси» ким экенин айтат.', 'Birim ağacı: türler, amirler, amaçlar, saat dilimleri, taşıma geçmişi. Oturum açan herkes okuyabilir; değişiklikler için `org.manage` gerekir. `GET /app/org/manager/:userId` kişinin «birim amiri»nin kim olduğunu döndürür.', '部门树：类型、负责人、用途、时区、调动历史。所有已登录用户均可读取；修改需要 `org.manage`。`GET /app/org/manager/:userId` 返回某人的“部门负责人”是谁。') },
  { key: 'employees', area: 'employees', prefix: ['/app/employees'], title: L('Сотрудники', 'Employees', 'Кызматкерлер', 'Çalışanlar', '员工'), intro: L('Реестр сотрудников: карточки, должности, документы, навыки и допуски, связь с учётной записью портала, импорт и выгрузка. Видимость решает сервер: `employees.view` — справочник (ФИО, должность, подразделение, рабочие контакты), `employees.hr` — всё, включая личные данные. Даты — `YYYY-MM-DD`.', 'The employee registry: cards, positions, documents, skills and clearances, the portal account link, import and export. The server decides visibility: `employees.view` is the directory (names, position, unit, work contacts), `employees.hr` everything including personal data. Dates are `YYYY-MM-DD`.', 'Кызматкерлер реестри: карточкалар, кызмат орундары, документтер, көндүмдөр жана уруксаттар, портал эсептик жазуусу менен байланыш, импорт жана жүктөп алуу. Эмнени көрсөтүүнү сервер чечет: `employees.view` — маалымдама (аты-жөнү, кызмат орду, бөлүм, жумушчу байланыштар), `employees.hr` — жеке маалыматтарды кошо баары. Даталар — `YYYY-MM-DD`.', 'Çalışan kayıt listesi: kartlar, pozisyonlar, belgeler, beceriler ve yetki belgeleri, portal hesabı bağlantısı, içe ve dışa aktarma. Görünürlüğe sunucu karar verir: `employees.view` rehberdir (adlar, pozisyon, birim, iş iletişim bilgileri), `employees.hr` kişisel veriler dahil her şeydir. Tarihler `YYYY-MM-DD`.', '员工台账：卡片、职位、证件、技能和资质证书、门户账户关联、导入和导出。可见范围由服务器决定：`employees.view` 为通讯录（姓名、职位、部门、工作联系方式），`employees.hr` 为包括个人数据在内的全部信息。日期为 `YYYY-MM-DD`。') },
  { key: 'qr', area: 'qr', prefix: ['/app/qr'], title: L('QR-коды', 'QR codes', 'QR-коддор', 'QR kodları', '二维码'), intro: L('Свои QR-коды владельца токена: тип, содержимое, шаблон и оформление; динамические коды сайта и их сканирования. Шаблоны — для `qr.admin`.', 'The token owner\'s own QR codes: type, content, template and design; dynamic website codes and their scans. Templates need `qr.admin`.', 'Токен ээсинин өз QR-коддору: түрү, мазмуну, үлгүсү жана жасалгасы; динамикалык коддор жана сканерлөөлөр. Үлгүлөр — `qr.admin` үчүн.', 'Belirteç sahibinin kendi QR kodları: tür, içerik, şablon ve tasarım; dinamik web sitesi kodları ve taramaları. Şablonlar `qr.admin` gerektirir.', '令牌所有者自己的二维码：类型、内容、模板和样式；动态网址码及其扫描。模板需要 `qr.admin`。') },
  { key: 'admin.users', area: 'admin.users', prefix: ['/admin/users', '/admin/groups', '/admin/roles', '/admin/permissions'], title: L('Пользователи и группы', 'Users and groups', 'Колдонуучулар жана топтор', 'Kullanıcılar ve gruplar', '用户和组'), intro: L('Учётные записи, группы и роли. Нужны права администратора у владельца токена.', 'Accounts, groups and roles. The token owner needs administrator rights.', 'Эсептик жазуулар, топтор жана ролдор. Токен ээсине администратордун укуктары керек.', 'Hesaplar, gruplar ve roller. Belirteç sahibinin yönetici haklarına sahip olması gerekir.', '账户、组和角色。令牌所有者需要管理员权限。') },
  { key: 'admin.security', area: 'admin.security', prefix: ['/admin/security'], title: L('Безопасность', 'Security', 'Коопсуздук', 'Güvenlik', '安全'), intro: L('Журнал событий безопасности и IP-правила.', 'Security events and IP rules.', 'Коопсуздук окуяларынын журналы жана IP эрежелери.', 'Güvenlik olayları ve IP kuralları.', '安全事件和 IP 规则。') },
  { key: 'admin.settings', area: 'admin.settings', prefix: ['/admin'], title: L('Администрирование', 'Administration', 'Администрлөө', 'Yönetim', '管理'), intro: L('Настройки портала, интеграции, сведения о системе.', 'Portal settings, integrations, system information.', 'Портал жөндөөлөрү, интеграциялар, система тууралуу маалымат.', 'Portal ayarları, entegrasyonlar, sistem bilgileri.', '门户设置、集成、系统信息。') },
  { key: 'common', area: null, prefix: ['/apps', '/status', '/settings'], title: L('Общее', 'General', 'Жалпы', 'Genel', '常规'), intro: L('Доступно любому действующему токену.', 'Available to any valid token.', 'Каалаган жарактуу токенге жеткиликтүү.', 'Geçerli her belirteç için kullanılabilir.', '任何有效令牌均可使用。') },
];

